const screens=[
 ['P001-login','P001 ログイン'],['P001-forgot','P001補助 パスワード再設定請求'],['P002','P002 ポータルトップ'],['P003','P003 全ツール'],['P004','P004 ツール詳細'],['P005','P005 利用マニュアル・FAQ'],['P006','P006 個人設定'],['P007','P007 問い合わせ・ご意見'],['P008','P008 お気に入りツール'],['P009','P009 初回パスワード設定・再設定'],['P010','P010 パスワード変更'],['P011','P011 サイト入場制限案内'],['A001-list','A001 ツール管理（一覧）'],['A001-edit','A001 ツール管理（編集）'],['A002-list','A002 ユーザー管理（一覧）'],['A002-edit','A002 ユーザー管理（編集）'],['A003','A003 ログ管理'],['A005-list','A005 問い合わせ管理（一覧）'],['A005-detail','A005 問い合わせ管理（詳細）'],['A006','A006 サイト管理']
];
const route=()=>location.hash.slice(1).split('?')[0]||'P002';
const link=(id,label)=>`<a href="#${id}">${label}</a>`;
const crumb=(...items)=>`<div class="breadcrumb">${items.map((x,i)=>i===items.length-1?`<span>${x[1]}</span>`:link(x[0],x[1])).join('')}</div>`;
const section=(title,body)=>`<section class="section"><div class="section-title">${title}</div>${body}</section>`;
const card=(title,body)=>`<div class="card">${title?`<div class="card-head">${title}</div>`:''}<div class="card-body">${body}</div></div>`;
const badge=s=>`<span class="badge badge-${s==='一般公開'||s==='公開'?'public':s==='限定公開'?'limited':'private'}">${s}</span>`;
const btn=(t,kind='primary',extra='')=>`<button class="btn ${kind==='primary'?'btn-primary':''}" ${extra}>${t}</button>`;
const field=(label,control,required=false)=>`<div class="form-label">${label}${required?'<span class="required">必須</span>':''}</div><div class="form-control">${control}</div>`;
const input=(value='',type='text')=>`<input class="input" type="${type}" value="${value}">`;
const select=(values,current)=>`<select>${values.map(v=>`<option ${v===current?'selected':''}>${v}</option>`).join('')}</select>`;
const table=(heads,rows)=>`<div class="table-wrap"><table class="data-table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr class="${r.class||''}">${r.cells.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
function header(admin=true){return `<header class="site-header"><div class="header-inner">${link('P002','<span class="brand">営業支援ポータルサイト</span>')}<nav class="nav"><div class="nav-group"><button>ツール一覧 ▼</button><div class="dropdown">${link('P003','全ツール')}${link('P008','お気に入り')}</div></div><div class="nav-group"><button>サポート ▼</button><div class="dropdown">${link('P006','個人設定')}${link('P005','利用マニュアル・FAQ')}${link('P007','問い合わせ・ご意見')}</div></div>${admin?`<div class="nav-group"><button>管理者用画面 ▼</button><div class="dropdown">${link('A002-list','ユーザー管理')}${link('A005-list','問い合わせ管理')}${link('A001-list','ツール管理')}${link('A006','サイト管理')}${link('A003','ログ管理')}</div></div>`:''}</nav><button class="user-menu">テスト太郎 ▼</button></div></header>`}
function shell(content,admin=true){return `${header(admin)}<div class="prototype-bar"><div class="prototype-inner"><strong>HTML画面モック</strong><select class="screen-select" aria-label="画面を選択">${screens.map(([id,n])=>`<option value="${id}" ${id===route()?'selected':''}>${n}</option>`).join('')}</select><span class="prototype-note">ダミーデータを使用しています</span></div></div><main class="main"><div class="container">${content}</div></main><footer class="footer">営業支援ポータル</footer>`}
function login(kind){const reset=kind!=='login';return `<div class="login-shell"><div class="login-card"><h1>営業支援ポータル</h1><h2>${reset?'パスワード再設定':'ログイン'}</h2><p>${reset?'登録されているメールアドレスを入力してください。再設定用のリンクをお送りします。':'メールアドレスとパスワードを入力してください。'}</p><div class="field"><label>メールアドレス</label>${input('','email')}</div>${reset?'':`<div class="field"><label>パスワード</label>${input('','password')}</div>`}${btn(reset?'再設定メールを送信':'ログイン')}<p class="login-help">${reset?link('P001-login','ログイン画面へ戻る'):link('P001-forgot','パスワードを忘れた方')}</p></div></div>`}
const notices=()=>`<div class="card">${[['2026/09/19(土)','秋のキャンペーンを開始しました','対象商品を期間限定の特別条件でご案内します。詳細をご確認ください。'],['','システムメンテナンスのお知らせ','9月23日にメンテナンスを実施します。作業中は一部機能をご利用いただけません。'],['2026/09/18(金)','新しいツールを公開しました','営業活動の効率化を支援する新しいツールを公開しました。ぜひご活用ください。']].map(x=>`<div class="notice-row"><div>${x[0]}</div><div class="notice-content"><h3>${x[1]}</h3><p>${x[2]}</p></div></div>`).join('')}</div>`;
function p002(){return shell(`${crumb(['P002','トップ'])}<div class="title-band">トップ</div>${section('お知らせ',notices())}${section('メニュー',`<div class="grid grid-3">${card('ツール一覧',`<div class="menu-card">${link('P003','全ツール <b>›</b>')}${link('P008','お気に入り <b>›</b>')}</div>`)}${card('サポート',`<div class="menu-card">${link('P006','個人設定 <b>›</b>')}${link('P005','利用マニュアル・FAQ <b>›</b>')}${link('P007','問い合わせ・ご意見 <b>›</b>')}</div>`)}${card('管理画面 <span class="badge badge-warn">管理者のみ</span>',`<div class="menu-card">${link('A002-list','ユーザー管理 <b>›</b>')}${link('A005-list','問い合わせ管理 <b>›</b>')}${link('A001-list','ツール管理 <b>›</b>')}${link('A006','サイト管理 <b>›</b>')}${link('A003','ログ管理 <b>›</b>')}</div>`)}</div>`)}`)}
const toolRows=()=>[{cells:['☆','顧客管理',link('P004','顧客情報検索ツール'),'顧客の基本情報・商談履歴・対応履歴を横断的に検索できます。','v2.3.0','2024/01/15',badge('一般公開'),link('P004','詳細 ›')]},{cells:['☆','提案・見積',link('P004','見積作成支援ツール'),'案件情報をもとに見積書を自動作成します。','v1.5.2','2024/02/01',badge('一般公開'),link('P004','詳細 ›')]},{class:'row-muted',cells:['☆','営業資料','提案資料テンプレート集','提案書・会社紹介・事例集をダウンロードできます。','v3.1.0','2024/01/25',badge('限定公開'),'']}];
function p003(fav=false){return shell(`${crumb(['P002','トップ'],[fav?'P008':'P003',fav?'お気に入り':'全ツール'])}<div class="title-band">${fav?'お気に入り':'全ツール'}</div><div class="tabs">${link('P003','全ツール')}${link('P008','お気に入り')}</div>${fav?card('',`<div class="empty"><p>お気に入りに登録されたツールはありません。</p>${link('P003','<span class="btn btn-primary">全ツールを見る</span>')}</div>`):table(['☆','カテゴリ','ツール名','ツール概要','バージョン','更新日','状態',''],toolRows())}`,false)}
function p004(){return shell(`${crumb(['P002','トップ'],['P003','全ツール'],['P004','顧客情報検索ツール'])}<h1 class="page-title">顧客情報検索ツール</h1>${section('お知らせ',`<div class="card"><div class="notice-row"><div>2024/04/12(金)</div><div class="notice-content"><h3>検索条件を追加しました</h3><p>担当部署と最終対応日を指定して、顧客情報を絞り込めるようになりました。</p></div></div><div class="notice-row"><div></div><div class="notice-content"><h3>操作マニュアルを更新しました</h3><p>新しい検索条件の操作方法と検索例を追加しました。</p></div></div></div>`)}${section('バージョン更新情報',table(['バージョン','更新日','更新内容'],[{cells:['v2.1.0（最新）','2024/04/12','検索条件を追加しました。']},{cells:['v2.0.0（現在）','2024/01/15','画面構成を改善しました。']}]))}${section('ツール概要',`<dl class="detail-list"><dt>カテゴリ</dt><dd>顧客管理</dd><dt>概要</dt><dd>顧客の基本情報・商談履歴・対応履歴を横断的に検索できます。</dd><dt>状態</dt><dd>${badge('一般公開')}</dd><dt>現在のバージョン</dt><dd>v2.0.0</dd><dt>更新日</dt><dd>2024/01/15(月)</dd></dl>`)}${section('利用者向け備考',card('',`顧客名または顧客コードを入力して検索してください。`))}${section('提供内容',card('',`${btn('Webツールを起動')} <a class="btn" href="#">操作マニュアルを開く</a>`))}`,false)}
function simple(title,id,body,admin=false){return shell(`${crumb(['P002','トップ'],[id,title])}<h1 class="page-title">${title}</h1>${body}`,admin)}
function p005(){return simple('利用マニュアル・FAQ','P005',`${section('利用マニュアル',card('',`<p>営業支援ポータルの基本操作をご案内します。</p><ol><li>ツール一覧から利用するツールを選びます。</li><li>ツール詳細で内容を確認し、起動またはダウンロードします。</li><li>よく使うツールは☆を選択してお気に入りに登録できます。</li></ol>`))}${section('FAQ',`<div class="card card-body faq"><details open><summary>処理結果はどこに保存されますか？</summary><p>処理結果はサイトに保存されません。必要な結果はダウンロードしてください。</p></details><details><summary>限定公開のツールを利用できますか？</summary><p>一般ユーザーは利用できません。必要な場合は管理者へお問い合わせください。</p></details><details><summary>ログインできない場合は？</summary><p>入力内容をご確認のうえ、パスワード再設定をご利用ください。</p></details></div>`)}`)}
var qa=(n,q,a)=>`<div class="qa-item qa-question"><div class="qa-mark">Q${n}</div><div class="qa-body">${q}</div></div><div class="qa-item qa-answer"><div class="qa-mark">A${n}</div><div class="qa-body">${a}</div></div>`;
var faqCategory=(title,items)=>`<section class="faq-category"><h2 class="faq-category-title">${title}</h2><div class="qa-list">${items}</div></section>`;
function p005(){const manual=section('利用マニュアル',`<div class="card manual-intro"><p>営業支援ポータルサイトの操作方法をまとめた利用マニュアル（PDF）をご用意しています。<br>初めてご利用の方は、まずこちらをご確認ください。</p><a class="btn manual-button" href="#"><span class="pdf-icon">📄</span>操作マニュアルを開く</a></div>`);const loginFaq=faqCategory('ログイン・アカウント',qa(1,'ログインID・パスワードを忘れてしまいました。どうすればよいですか？','ログイン画面の「パスワードを忘れた方」から、再設定手続きを行ってください。<br>ログインIDが不明な場合は、社内のシステム管理者までお問い合わせください。')+qa(2,'アカウントのロックがかかってしまいました。','一定回数以上のログイン失敗により、セキュリティ保護のためアカウントがロックされます。<br>しばらく時間をおいてから再度お試しいただくか、システム管理者までご連絡ください。'));const toolFaq=faqCategory('ツールの利用',qa(3,'ツールで作成したデータはどこに保存されますか？','処理結果はサイトに保存されません。必要な結果はダウンロードしてください。')+qa(4,'ツールが正常に動作しない場合はどうすればよいですか？','まずはブラウザーのキャッシュをクリアし、再度お試しください。<br>解決しない場合は、マニュアルをご確認のうえ、サポート窓口までお問い合わせください。'));return simple('利用マニュアル・FAQ','P005',manual+section('よくあるご質問（FAQ）',loginFaq+toolFaq))}
var qa=(n,q,a)=>`<div class="qa-item qa-question"><div class="qa-mark">Q${n}</div><div class="qa-body">${q}</div></div><div class="qa-item qa-answer"><div class="qa-mark">A${n}</div><div class="qa-body">${a}</div></div>`;
var faqCategory=(title,items)=>`<section class="faq-category"><h2 class="faq-category-title">${title}</h2><div class="qa-list">${items}</div></section>`;
function p005(){const manual=section('利用マニュアル',`<div class="card manual-intro"><p>営業支援ポータルサイトの操作方法をまとめた利用マニュアル（PDF）をご用意しています。<br>初めてご利用の方は、まずこちらをご確認ください。</p><a class="btn manual-button" href="#"><span class="pdf-icon">📄</span>操作マニュアルを開く</a></div>`);const loginFaq=faqCategory('ログイン・アカウント',qa(1,'ログインID・パスワードを忘れてしまいました。どうすればよいですか？','ログイン画面の「パスワードを忘れた方」から、再設定手続きを行ってください。<br>ログインIDが不明な場合は、社内のシステム管理者までお問い合わせください。')+qa(2,'アカウントのロックがかかってしまいました。','一定回数以上のログイン失敗により、セキュリティ保護のためアカウントがロックされます。<br>しばらく時間をおいてから再度お試しいただくか、システム管理者までご連絡ください。'));const toolFaq=faqCategory('ツールの利用',qa(3,'ツールで作成したデータはどこに保存されますか？','処理結果はサイトに保存されません。必要な結果はダウンロードしてください。')+qa(4,'ツールが正常に動作しない場合はどうすればよいですか？','まずはブラウザーのキャッシュをクリアし、再度お試しください。<br>解決しない場合は、マニュアルをご確認のうえ、サポート窓口までお問い合わせください。'));return simple('利用マニュアル・FAQ','P005',manual+section('よくあるご質問（FAQ）',loginFaq+toolFaq))}
function p006(){return simple('個人設定','P006',section('通知設定',card('',`<label><input type="checkbox" checked> システムのお知らせメールを受信する</label><br><br><label><input type="checkbox" checked> お気に入りツールのお知らせメールを受信する</label><div class="actions">${btn('保存')}</div>`)))}
function p007(){return simple('問い合わせ・ご意見','P007',section('入力内容',`<div class="card"><div class="form-grid">${field('カテゴリ',select(['選択してください','質問','要望','意見','不具合報告','その他'],'選択してください'),true)}${field('対象',select(['選択してください','ポータルサイト','顧客情報検索ツール','見積作成支援ツール','その他'],'選択してください'),true)}${field('内容',`<textarea maxlength="2000" placeholder="2000文字以内で入力してください"></textarea>`,true)}${field('添付ファイル',`<input type="file"><p>任意・1ファイル最大10MB（PDF、Excel、Word、CSV、テキスト、PNG、JPEG）</p>`)}</div><div class="actions">${btn('送信内容を確認')}</div></div>`))}
function password(title,id,intro){return simple(title,id,`${card('',`<p>${intro}</p><div class="form-grid">${id==='P010'?field('現在のパスワード',input('','password'),true):''}${field('新しいパスワード',input('','password'),true)}${field('新しいパスワード（確認）',input('','password'),true)}</div><p class="info">14～64文字の半角英数字と記号を使用してください。</p><div class="actions">${btn(title==='パスワード変更'?'変更':'設定')}</div>`)}`)}
function p011(){return `<div class="login-shell"><div class="login-card"><h1>営業支援ポータル</h1><h2>現在、サイトを利用できません</h2><div class="info warning">現在メンテナンスを実施しています。しばらく時間をおいてから、もう一度アクセスしてください。</div><p>ご不便をおかけしますが、ご理解のほどお願いいたします。</p></div></div>`}
function adminList(kind){if(kind==='tool')return simple('ツール管理','A001-list',`${section('検索条件',`<div class="toolbar"><div class="field"><label>カテゴリ</label>${select(['すべて','顧客管理','提案支援'],'すべて')}</div><div class="field"><label>担当者</label>${select(['すべて','鈴木 花子','山田 太郎'],'すべて')}</div><div class="field"><label>状態</label>${select(['すべて','一般公開','限定公開','非公開'],'すべて')}</div>${btn('絞り込み')}${btn('条件クリア','secondary')}</div>`)}${section('ツール一覧',table(['カテゴリ','ツール名','担当者','状態','現在のバージョン','詳細'],[{cells:['顧客管理',link('A001-edit','顧客管理ツール'),'鈴木 花子',badge('一般公開'),'v2.3.0',link('A001-edit','詳細 ›')]},{class:'row-muted',cells:['提案支援',link('A001-edit','提案書作成ツール'),'山田 太郎',badge('限定公開'),'v1.8.1',link('A001-edit','詳細 ›')]},{class:'row-muted',cells:['データ分析',link('A001-edit','営業分析ダッシュボード'),'佐藤 一郎',badge('非公開'),'v1.4.2',link('A001-edit','詳細 ›')]}]))}`,true);
return simple('ユーザー管理','A002-list',`${section('検索条件',`<div class="toolbar"><div class="field"><label>氏名・メールアドレス</label>${input()}</div><div class="field"><label>権限</label>${select(['すべて','システム管理者','一般ユーザー'],'すべて')}</div><div class="field"><label>状態</label>${select(['すべて','有効','無効'],'すべて')}</div>${btn('検索')}${btn('条件クリア','secondary')}</div>`)}${section('ユーザー一覧',table(['表示名','メールアドレス','権限','状態','最終利用日時','詳細'],[{cells:['テスト太郎','taro@example.local','システム管理者',badge('一般公開'),'2026/09/19 09:12',link('A002-edit','詳細 ›')]},{cells:['鈴木 花子','hanako@example.local','一般ユーザー',badge('一般公開'),'2026/09/18 16:40',link('A002-edit','詳細 ›')]},{class:'row-muted',cells:['山田 次郎','jiro@example.local','一般ユーザー',badge('非公開'),'2026/08/30 10:03',link('A002-edit','詳細 ›')]}]))}`,true)}
const userState=active=>`<span class="user-state ${active?'user-active':'user-inactive'}">${active?'有効':'無効'}</span>`;
function a002list(){return simple('ユーザー管理','A002-list',`${section('検索条件',`<div class="toolbar user-toolbar"><div class="field"><label>表示名</label>${input()}</div><div class="field"><label>メールアドレス</label>${input()}</div><div class="field"><label>権限</label>${select(['すべて','システム管理者','一般ユーザー'],'すべて')}</div><div class="field"><label>状態</label>${select(['すべて','有効','無効'],'すべて')}</div>${btn('検索')}${btn('条件クリア','secondary')}</div>`)}${section('ユーザー一覧',table(['表示名','メールアドレス','権限','状態','最終利用日時','詳細'],[{cells:['テスト太郎','taro@example.local','システム管理者',userState(true),'2026/09/19 09:12',link('A002-edit','詳細 ›')]},{cells:['鈴木 花子','hanako@example.local','一般ユーザー',userState(true),'2026/09/18 16:40',link('A002-edit','詳細 ›')]},{class:'row-muted',cells:['山田 次郎','jiro@example.local','一般ユーザー',userState(false),'2026/08/30 10:03',link('A002-edit','詳細 ›')]}]))}`,true)}
