function render(){const id=route();let html;switch(id){case'P001-login':html=login('login');break;case'P001-forgot':html=login('forgot');break;case'P002':html=p002();break;case'P003':html=p003();break;case'P004':html=p004();break;case'P005':html=p005();break;case'P006':html=p006();break;case'P007':html=p007();break;case'P008':html=p003(true);break;case'P009':html=password('パスワード設定','P009','新しいパスワードを設定してください。');break;case'P010':html=password('パスワード変更','P010','パスワードの漏えいが疑われる場合は変更してください。');break;case'P011':html=p011();break;case'A001-list':html=adminList('tool');break;case'A001-edit':html=a001editV2();break;case'A002-list':html=adminList('user');break;case'A002-edit':html=a002edit();break;case'A003':html=a003();break;case'A005-list':html=a005list();break;case'A005-detail':html=a005detail();break;case'A006':html=simple('サイト管理','A006',section('システムのお知らせ',noticeEditor()),true);break;default:location.hash='P002';return}document.querySelector('#app').innerHTML=html;document.querySelector('.screen-select')?.addEventListener('change',e=>location.hash=e.target.value);const versionSelect=document.querySelector('.current-version-select');versionSelect?.addEventListener('change',e=>{document.querySelector('.release-date b').textContent=e.target.value});document.querySelectorAll('button').forEach(b=>{if(!b.disabled&&!b.closest('.nav'))b.addEventListener('click',()=>{const t=document.createElement('div');t.className='toast';t.textContent='画面モックのため、データは更新されません。';document.body.append(t);setTimeout(()=>t.remove(),1800)})});window.scrollTo(0,0)}
function login(kind){if(kind!=='login')return `<div class="login-shell"><div class="login-card"><h1>営業支援ポータル</h1><h2>パスワード再設定</h2><p>登録されているメールアドレスを入力してください。</p>${input('','email')}<br><br>${btn('再設定メールを送信')}<p class="login-help">${link('P001-login','ログイン画面へ戻る')}</p></div></div>`;return `<div class="login-shell"><div class="login-card"><h1>営業支援ポータル</h1>${card('ログイン',`<div class="field"><label>メールアドレス</label>${input('','email')}</div><div class="field"><label>パスワード</label>${input('','password')}</div>${btn('ログイン')}<p class="login-help">${link('P001-forgot','パスワードを忘れた方')}</p>`)}<div class="login-contact">${card('初めてご利用の方',`<p>本ポータルのご利用には、アカウントの発行が必要です。</p><p>ご利用を希望される場合は、社内のシステム担当までお問い合わせください。</p><p><b>お問い合わせ先</b><br>営業企画部 システム担当　内線：1234</p>`)}</div></div></div>`}
