function noticeEditor(){const rows=[{cells:['<input type="checkbox">',badge('公開'),'2026/09/18 14:30','2026/09/18 14:32','新規ツールをリリースしました。','<div class="notice-preview">営業活動を支援する新しいツールを公開しました。詳しい利用方法はツール詳細をご確認ください。</div>','<button class="btn btn-small notice-edit-button" data-title="新規ツールをリリースしました。" data-body="営業活動を支援する新しいツールを公開しました。" data-public="true">編集</button>']}];return section('登録済みのお知らせ',`${table(['','公開状態','更新日時','最終送信日時','タイトル','内容','編集'],rows)}<div class="notice-list-actions">${btn('選択したお知らせを送信')}<button id="new-notice-button" class="btn btn-primary">新規登録</button></div>`)+`<div id="notice-editor-panel" class="editor-panel hidden">${section('お知らせ編集',`<div id="notice-editor" class="card"><div class="form-grid">${field('タイトル','<input id="notice-title" class="input">',true)}${field('内容','<textarea id="notice-body"></textarea>',true)}${field('公開状態','<label><input id="notice-public" type="radio" name="notice-publication"> 公開</label>　<label><input id="notice-private" type="radio" name="notice-publication" checked> 非公開</label>')}</div><div class="actions">${btn('保存')}${btn('キャンセル','secondary')}</div></div>`)}</div>`}
function a001edit(){const vs=[['2.1.0','2026-09-19','検索条件を追加'],['2.0.0','2026-09-10','画面構成を改善'],['1.5.0','2026-08-20','帳票出力を追加']];const choice=`<div class="version-choice"><select class="current-version-select">${vs.map(v=>`<option value="${v[1].replaceAll('-','/')}" ${v[0]==='2.0.0'?'selected':''}>Ver.${v[0]}</option>`).join('')}</select><span class="release-date">リリース日：<b>2026/09/10</b></span></div>`;const rows=vs.map(v=>({class:v[0]==='2.0.0'?'current-version-row':'',cells:[`Ver.${v[0]}`,v[1].replaceAll('-','/'),v[2],`<button class="btn btn-small version-edit-button" data-version="${v[0]}" data-date="${v[1]}" data-description="${v[2]}">編集</button>`]}));const editor=`<div id="version-editor-panel" class="editor-panel hidden">${card('バージョン編集',`<div class="form-grid">${field('バージョン','<div class="version-input"><b>Ver.</b><input id="version-value" class="input"></div>',true)}${field('更新日','<input id="version-date" class="input" type="date">',true)}${field('更新内容','<textarea id="version-description"></textarea>',true)}</div><div class="actions">${btn('保存')}${btn('キャンセル','secondary')}</div>`)}</div>`;const versions=section('バージョン更新情報',`<div class="current-version-panel"><strong>現在のバージョン</strong>${choice}</div>${table(['バージョン','更新日','更新内容','編集'],rows)}<div class="version-list-actions"><button id="new-version-button" class="btn btn-primary">新規登録</button></div>${editor}`);const overview=section('ツール概要',card('',`<div class="form-grid">${field('ツール名',input('営業分析ツール'),true)}${field('概要','<textarea>営業実績を集計・分析します。</textarea>')}${field('備考','<textarea>大量データの処理には時間がかかる場合があります。</textarea>')}</div><div class="actions">${btn('保存')}</div>`));const contents=section('コンテンツ',card('配布ファイル','<div class="upload">sales-tool.zip　<input type="file"> '+btn('差し替え')+'</div>'));return simple('ツール編集','A001-edit',noticeEditor()+versions+overview+contents,true)}
function header(admin=true){return `<header class="site-header"><div class="header-inner">${link('P002','<span class="brand">営業支援ポータルサイト</span>')}<nav class="nav"><div class="nav-group"><button>ツール一覧 ▼</button><div class="dropdown">${link('P003','全ツール')}${link('P008','お気に入りツール')}</div></div><div class="nav-group"><button>サポート ▼</button><div class="dropdown">${link('P006','個人設定')}${link('P005','利用マニュアル・FAQ')}${link('P007','問い合わせ・ご意見')}</div></div>${admin?`<div class="nav-group"><button>管理者用画面 ▼</button><div class="dropdown">${link('A002-list','ユーザー管理')}${link('A005-list','問い合わせ管理')}${link('A001-list','ツール管理')}${link('A006','サイト管理')}${link('A003','ログ管理')}</div></div>`:''}</nav><button class="user-menu">テスト太郎 ▼</button></div></header>`}
