function p003(fav=false){const tab=(id,label,active)=>`<a href="#${id}" class="tool-tab${active?' active':''}" ${active?'aria-current="page"':''}>${label}</a>`;return shell(`${crumb(['P002','トップ'],[fav?'P008':'P003',fav?'お気に入りツール':'全ツール'])}<div class="title-band">${fav?'お気に入りツール':'全ツール'}</div><nav class="tabs tool-tabs" aria-label="ツール一覧の切り替え">${tab('P003','全ツール（3）',!fav)}${tab('P008','★ お気に入りツール（0）',fav)}</nav>${fav?card('',`<div class="empty"><p>お気に入りツールは登録されていません。</p>${link('P003','<span class="btn btn-primary">全ツールを見る</span>')}</div>`):table(['☆','カテゴリ','ツール名','ツール概要','バージョン','更新日','状態',''],toolRows())}`,false)}
