document.addEventListener('click',e=>{if(e.target.matches('.notice-edit-button')||e.target.id==='new-notice-button')document.querySelector('#notice-editor-panel')?.classList.remove('hidden');if(e.target.matches('.version-edit-button')){document.querySelector('#version-value').value=e.target.dataset.version;document.querySelector('#version-date').value=e.target.dataset.date;document.querySelector('#version-description').value=e.target.dataset.description;document.querySelector('#version-editor-panel').classList.remove('hidden')}if(e.target.id==='new-version-button'){document.querySelector('#version-value').value='';document.querySelector('#version-date').value='';document.querySelector('#version-description').value='';document.querySelector('#version-editor-panel').classList.remove('hidden')}});
document.addEventListener('click',e=>{if(e.target.matches('.editor-panel .btn')&&e.target.textContent.trim()==='キャンセル')e.target.closest('.editor-panel')?.classList.add('hidden')});
document.addEventListener('click',e=>{if(e.target.id==='clear-inquiry-period')document.querySelectorAll('.inquiry-date').forEach(input=>input.value='')});
document.addEventListener('click',e=>{if(e.target.id==='new-user-import-button')document.querySelector('#user-import-panel')?.classList.toggle('hidden')});
document.addEventListener('change',e=>{if(e.target.id==='log-type'){const usage=e.target.value==='usage';document.querySelector('#usage-extract-field')?.classList.toggle('hidden',!usage);const note=document.querySelector('#log-export-note');if(note)note.textContent=usage?'ツール利用ログの明細、またはツールごとの重複を除いた利用者数を出力します。':'選択したログの全列・全件の明細を出力します。'}});
document.addEventListener('click', e => {
  const target = e.target;
  if (target.id === 'mock-logout') location.hash = 'P001-login';
  if (target.matches('.version-edit-button')) document.querySelector('#version-owner').value = target.dataset.owner || '';
  if (target.id === 'new-version-button') document.querySelector('#version-owner').value = '';
  if (target.matches('.resource-edit') || target.id === 'new-resource-button') {
    const editing = target.matches('.resource-edit');
    document.querySelector('#resource-name').value = editing ? target.dataset.name : '';
    document.querySelector('#resource-current-file').textContent = editing ? target.dataset.file : '未登録';
    document.querySelector('#resource-file').value = '';
    document.querySelector('#resource-file').required = !editing;
    document.querySelector('#resource-editor-title').textContent = editing ? '関連資料の編集' : '関連資料の新規登録';
    document.querySelector('#resource-file-hint').textContent = editing ? '表示名だけ変更する場合は、ファイルの選択は不要です。' : '新規登録時はファイルを選択してください。';
    document.querySelector('#resource-editor-panel').classList.remove('hidden');
  }
  if (target.id === 'search-users' || target.id === 'clear-users') {
    const toolbar = document.querySelector('.user-lock-toolbar');
    if (target.id === 'clear-users') {
      toolbar.querySelectorAll('input').forEach(x => x.value = '');
      toolbar.querySelectorAll('select').forEach(x => x.selectedIndex = 0);
    }
    const inputs = toolbar.querySelectorAll('input');
    const filters = toolbar.querySelectorAll('select');
    document.querySelectorAll('.data-table tbody tr').forEach(row => {
      const cells = row.cells;
      row.hidden = !(
        cells[0].textContent.includes(inputs[0].value.trim()) &&
        cells[1].textContent.toLowerCase().includes(inputs[1].value.trim().toLowerCase()) &&
        (filters[0].value === 'すべて' || cells[2].textContent === filters[0].value) &&
        (filters[1].value === 'すべて' || cells[3].textContent === filters[1].value) &&
        (filters[2].value === 'すべて' || cells[4].textContent === filters[2].value)
      );
    });
  }
});
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') {
    const menu = document.querySelector('.account-menu');
    if (menu?.open) { menu.open = false; menu.querySelector('summary').focus(); }
  }
});
document.addEventListener('click', e => {
  const menu = document.querySelector('.account-menu');
  if (menu?.open && !menu.contains(e.target)) menu.open = false;
});
addEventListener('hashchange',render);render();
